/* eslint-disable */
/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
export type AccountDetailsInput = {
  /** Required: the version of the terms and conditions the person ticked the box for, from `currentLegalDocument(kind: TERMS)`. Optional in the schema only so that leaving it out answers TERMS_NOT_ACCEPTED. */
  acceptedTermsVersion?: string | null | undefined;
  /** ISO 3166-1 alpha-2 country they live in. */
  country: string;
  firstName: string;
  /** The person confirmed they are 18 or older. */
  isAdult: boolean;
  lastName: string;
  /** The language the person chose for the app. */
  locale: Locale;
  ticket: string;
  /** The device's IANA time zone. */
  timeZone: string;
};

/** What the account may do. Anything but ACTIVE is limited mode: no new tasks, offers or bookings, while history, open bookings, chat on them, data export and account deletion keep working. */
export type AccountState =
  | 'ACTIVE'
  | 'DELETION_PENDING'
  | 'SUSPENDED'
  | 'TERMS_UPDATE_REQUIRED';

/** Which side of a booking. */
export type BookingSide =
  | 'HELPER'
  | 'POSTER';

/** Where a booking is, from checkout (AWAITING_PAYMENT) to CLOSED. FUNDS_HELD and the other money-confirmed statuses are set only from Stripe's webhook. */
export type BookingStatus =
  | 'AWAITING_PAYMENT'
  | 'CANCEL_REQUESTED'
  | 'CLOSED'
  | 'DISPUTED'
  | 'FUNDS_HELD'
  | 'INCIDENT_PAUSED'
  | 'NO_ACCESS_REPORTED'
  | 'PAID_OUT'
  | 'PARTIALLY_SETTLED'
  | 'PAYMENT_FAILED'
  | 'PAYMENT_REQUESTED'
  | 'REFUNDED'
  | 'RELEASED';

/** The cancellation policy row that applies (bookings/cancellation.py): which refund the poster gets. */
export type CancellationCase =
  /** 24 h or more before the start: full refund. */
  | 'EARLY'
  /** Within 1 h of accepting: full refund. */
  | 'GRACE_PERIOD'
  /** The helper cancelled: full refund. */
  | 'HELPER_CANCEL'
  /** Under 24 h before the start: the helper keeps 25% (EUR 5 to 20). */
  | 'LATE'
  /** Late, but a registered business inside its 14-day withdrawal period: full refund. */
  | 'LATE_TRADER_WITHDRAWAL'
  /** The helper couldn't get in: the call-out is paid. */
  | 'NO_ACCESS_CALL_OUT'
  /** Nobody's fault: full refund. */
  | 'NO_FAULT'
  /** Withdrawal from the contract before the start: full refund. */
  | 'WITHDRAWAL'
  /** Withdrawal after the start: the helper keeps the share of the work done. */
  | 'WITHDRAWAL_PRO_RATA';

/** The two separate, unticked checkout boxes. Both must be ticked, for the cancellation policy version shown, which must be the one in force. */
export type CheckoutConsentInput = {
  /** I accept the cancellation and refund policy. */
  cancellationPolicyAccepted: boolean;
  /** The CANCELLATION version the checkout showed. */
  cancellationVersion: string;
  /** I ask for the booking to be arranged now and the task done on the date I chose, which may be within my 14-day withdrawal period. */
  earlyStartRequested: boolean;
  /** The language the checkout showed the policy in; its version is checked in it. */
  language: Locale;
  platform: SessionPlatform;
  /** The tick-box pair shown, from the offer's helperIsTrader; it must match the helper's status when the offer is accepted (CONSENT_WORDING_CHANGED). */
  variant: CheckoutConsentVariant;
};

/** Which of the CANCELLATION policy's two tick-box pairs the checkout showed: the one for a private helper or the one for a registered business (trader). */
export type CheckoutConsentVariant =
  | 'PRIVATE_HELPER'
  | 'TRADER_HELPER';

/** Why a checkout ended without a payment (PAYMENT_FAILED). */
export type CheckoutFailureReason =
  /** Nobody paid within 30 minutes of the last card attempt, or 60 minutes of accepting. The offer is open again unless the helper withdrew it. */
  | 'CHECKOUT_EXPIRED'
  /** The helper withdrew the offer during checkout. */
  | 'OFFER_WITHDRAWN'
  /** The payment couldn't be started at Stripe. */
  | 'PAYMENT_NOT_STARTED';

export type CreateCareContactInput = {
  area: string;
  /** The poster confirmed the person agreed to having their details saved. */
  hasTheirAgreement: boolean;
  language?: Locale;
  name: string;
  noSmartphone?: boolean;
  /** Mobile or landline, international (+49 ...) or national Croatian (020 ...). */
  phone: string;
};

export type CreateUploadUrlInput = {
  /** "image/jpeg", "image/png" or "image/webp". */
  contentType: string;
  purpose: UploadPurpose;
  /** The file's exact size in bytes. */
  sizeBytes: number;
};

export type DeviceInput = {
  /** The `AuthSession.deviceToken` this device kept from its last sign-in. */
  deviceToken?: string | null | undefined;
  /** E.g. "iPhone" or "Firefox on Mac". */
  name?: string;
  platform: SessionPlatform;
};

/** Codes returned in `errors[].extensions.code`. Clients show the translation `errors.<CODE>` from packages/i18n; the error message itself is for developers only. */
export type ErrorCode =
  /** The account is waiting to be deleted once its open bookings and payouts close; it can't post, offer or book. */
  | 'ACCOUNT_DELETION_PENDING'
  /** The account is suspended: it can't post, offer or book, but can finish open bookings, appeal, export its data and delete the account. */
  | 'ACCOUNT_SUSPENDED'
  /** The booking's status doesn't allow this action now, or not for you; refetch the booking to see its current status. */
  | 'BOOKING_ACTION_NOT_ALLOWED'
  /** No such booking of the signed-in user. */
  | 'BOOKING_NOT_FOUND'
  /** The task's budget is below the minimum task price of EUR 10. */
  | 'BUDGET_BELOW_MINIMUM'
  /** An obrt or company sends offers only once its registered business address is on file: the contract confirmation shows it to the poster. `myHelperProfile.missing` lists BUSINESS_ADDRESS. */
  | 'BUSINESS_ADDRESS_REQUIRED'
  /** The task's poster books for a business, so only registered helpers (obrt or company) can offer on it or be booked for it. */
  | 'BUSINESS_POSTER_REGISTERED_ONLY'
  /** The refund changed since you opened the cancel screen (a deadline passed, such as 24 hours before the start); check it again. Nothing was cancelled. */
  | 'CANCELLATION_CHANGED'
  /** Saving an on-site contact needs the poster's confirmation that the person agreed to having their details saved. */
  | 'CARE_CONTACT_AGREEMENT_REQUIRED'
  /** An open task or an active booking uses this on-site contact; it can be deleted once the task or booking closes. */
  | 'CARE_CONTACT_IN_USE'
  /** A booking visit with this on-site contact has started; it can be changed again once the booking closes. */
  | 'CARE_CONTACT_LOCKED'
  /** No such on-site contact of the signed-in user. */
  | 'CARE_CONTACT_NOT_FOUND'
  /** TaskBeavo doesn't accept this kind of task: rides (driving people), medical care and personal care are not allowed. */
  | 'CATEGORY_NOT_ALLOWED'
  /** The checkout is no longer open: it was paid, expired or ended because the offer was withdrawn. Refetch the booking to see which. */
  | 'CHECKOUT_CLOSED'
  /** Checkout needs both boxes ticked, the cancellation policy and the early-start request, for the cancellation policy version in force; reload it if it changed. */
  | 'CONSENT_REQUIRED'
  /** The helper's private or business status changed since the checkout was shown, so the tick boxes read differently now; nothing was booked. Reload the offer and tick them again. */
  | 'CONSENT_WORDING_CHANGED'
  /** Evidence photos are taken in the TaskBeavo app, not uploaded from the web. */
  | 'EVIDENCE_NEEDS_APP'
  /** The service fee changed since you opened the checkout (a new price list took effect); check the new total. */
  | 'FEE_CHANGED'
  /** Helpers need a home address in Croatia; TaskBeavo isn't open to helpers elsewhere yet. Offer joinWaitlist. */
  | 'HELPER_ADDRESS_NOT_IN_CROATIA'
  /** The helper's payout account can't receive payments right now, so nothing was charged; the offer stays open. Try again later or choose another offer. */
  | 'HELPER_CANNOT_TAKE_PAYMENTS'
  /** Sending offers needs a complete helper profile; `myHelperProfile.missing` lists what is still missing. */
  | 'HELPER_PROFILE_INCOMPLETE'
  /** A name, country or time zone in the account details is missing or invalid. */
  | 'INVALID_ACCOUNT_DETAILS'
  /** A company's OIB can't be a person's OIB (the helper's own or another helper's), and an obrt's OIB is its owner's own OIB: leave it out for an obrt. */
  | 'INVALID_BUSINESS_OIB'
  /** The on-site contact's name or area is missing or longer than 100 characters. */
  | 'INVALID_CARE_CONTACT'
  /** The on-site contact's phone isn't a valid mobile or landline number. */
  | 'INVALID_CARE_CONTACT_PHONE'
  /** The emailed or SMS code is wrong, expired, already used or burnt after too many wrong tries; request a new one. */
  | 'INVALID_CODE'
  /** The email address isn't a valid address. */
  | 'INVALID_EMAIL'
  /** The arrival time isn't valid: missing, outside 1 to 240 minutes, or for running late, not after the booked start. */
  | 'INVALID_ETA'
  /** A helper profile field is missing, too long or invalid: a name, the street, city or Croatian postal code, the country code, an implausible date of birth, or business details without the BUSINESS status. */
  | 'INVALID_HELPER_DETAILS'
  /** The IBAN isn't a valid IBAN of a bank account in the EU. */
  | 'INVALID_IBAN'
  /** The offer's price is too high or its message longer than 1000 characters. */
  | 'INVALID_OFFER_DETAILS'
  /** The OIB isn't 11 digits with a matching check digit (ISO 7064 MOD 11,10). */
  | 'INVALID_OIB'
  /** The phone number isn't a valid mobile number. */
  | 'INVALID_PHONE_NUMBER'
  /** The business kind is unknown, or its name is empty or over 200 characters. */
  | 'INVALID_POSTER_BUSINESS'
  /** The Google or Apple sign-in couldn't be verified (expired, for another app, or its nonce is wrong or used); start the sign-in again with a new nonce. */
  | 'INVALID_PROVIDER_TOKEN'
  /** The push token isn't an Expo push token, or is still registered to another signed-in account. */
  | 'INVALID_PUSH_TOKEN'
  /** The task's time window must start from now, end after it starts and end within 60 days; a task without a flexible date needs one. */
  | 'INVALID_TASK_DATES'
  /** A required task field is missing (category, title, description, address, budget), a text is too long, the coordinates are invalid or there are more than 10 photos. */
  | 'INVALID_TASK_DETAILS'
  /** The VAT ID isn't a valid EU VAT number (a Croatian one is HR and the OIB). */
  | 'INVALID_VAT_ID'
  /** The city is missing or too long, or the country code isn't two letters. */
  | 'INVALID_WAITLIST_DETAILS'
  /** The name or email address on a withdrawal statement is empty or invalid. */
  | 'INVALID_WITHDRAWAL_DETAILS'
  /** Too many wrong sign-in codes for this email address: sign-in is locked for 30 minutes. `extensions.retryAfterSeconds` says how long is left. */
  | 'LOCKED'
  /** A mutation was sent over the WebSocket; send mutations over HTTP. */
  | 'MUTATIONS_REQUIRE_HTTP'
  /** Booking and payment notifications are part of the service and stay on. */
  | 'NOTIFICATION_PREFERENCE_LOCKED'
  /** The time to answer the no-fault request is over (the helper's 48 hours, or support decided), so the answer isn't taken. Refetch the booking. */
  | 'NO_FAULT_REPLY_CLOSED'
  /** You already have an open offer on this task; change or renew that one. */
  | 'OFFER_ALREADY_SENT'
  /** The helper changed the offer's price since you opened it; check it again. */
  | 'OFFER_CHANGED'
  /** The offer's message may contain a phone number, email address or link; remove it and send the offer again. */
  | 'OFFER_MESSAGE_CONTACT_DETAILS'
  /** The task changed since the helper sent this offer, and they haven't confirmed it yet; it can be accepted once they do. */
  | 'OFFER_NEEDS_UPDATE'
  /** This offer can no longer be accepted, so nothing was charged; choose another offer. */
  | 'OFFER_NOT_AVAILABLE'
  /** The offer is no longer open: it was withdrawn or has expired. An expired offer can be renewed. */
  | 'OFFER_NOT_EDITABLE'
  /** No such offer of the signed-in helper. */
  | 'OFFER_NOT_FOUND'
  /** Helpers can't send offers on their own tasks. */
  | 'OFFER_ON_OWN_TASK'
  /** The offer's price is below the minimum task price of EUR 10. */
  | 'OFFER_PRICE_BELOW_MINIMUM'
  /** The OIB is already on another helper's profile; one OIB belongs to one helper. Contact support if it is yours. */
  | 'OIB_IN_USE'
  /** The task's location is outside every active TaskBeavo service area: outside Croatia, or in a Croatian city TaskBeavo doesn't serve yet. Offer joinWaitlist. */
  | 'OUT_OF_SERVICE_AREA'
  /** The payment couldn't be started, so nothing was charged; the offer stays open. Try again. */
  | 'PAYMENT_UNAVAILABLE'
  /** Sending offers needs a Stripe payout account that can receive payments: finish Stripe onboarding, or give Stripe the information it asked for (startPayoutOnboarding). `myHelperProfile.payoutAccount` has the status. */
  | 'PAYOUT_ACCOUNT_NOT_READY'
  /** Stripe rejected the payout account, so onboarding can't continue; support explains why and how to appeal. */
  | 'PAYOUT_ACCOUNT_REJECTED'
  /** TaskBeavo can't send SMS to mobile numbers of this country yet (no sender for it, e.g. +1 numbers, or switched off); use another mobile number. */
  | 'PHONE_COUNTRY_NOT_SUPPORTED'
  /** Posting a task, sending an offer and chatting need a verified mobile number; verify it with requestPhoneCode and verifyPhoneCode. */
  | 'PHONE_NOT_VERIFIED'
  /** The number is already verified on another account; one number verifies one account. Contact support if it is yours. */
  | 'PHONE_NUMBER_IN_USE'
  /** You have an open checkout with a private helper; finish or leave it before adding your business. */
  | 'POSTER_BUSINESS_CHECKOUT_OPEN'
  /** Google or Apple didn't share a verified email address, which a new account needs; allow sharing the email, or sign in with an email code. */
  | 'PROVIDER_EMAIL_MISSING'
  /** Google or Apple couldn't be reached to check the sign-in; try again in a few minutes, or sign in with an email code. */
  | 'PROVIDER_UNAVAILABLE'
  /** Too many calls of this mutation from this client. `extensions.retryAfterSeconds`, when present, says how long to wait (up to a day for SMS codes); otherwise retry after a minute. */
  | 'RATE_LIMITED'
  /** The web app's /api routes refused a request that didn't come from its own pages (cross-site request forgery check); reload the page and try again. */
  | 'REQUEST_REJECTED'
  /** The country of residence must be an EU member state, as an ISO 3166-1 alpha-2 code (HR, DE, AT, ...). */
  | 'RESIDENCE_COUNTRY_NOT_ALLOWED'
  /** No such active service area; pick one from serviceAreas. */
  | 'SERVICE_AREA_NOT_FOUND'
  /** The refresh token is unknown, expired, reused or its session was revoked; sign in again. */
  | 'SESSION_EXPIRED'
  /** The account-details ticket is invalid, expired or its account already exists; sign in again with a new code. */
  | 'SIGNUP_TICKET_EXPIRED'
  /** The "This wasn't me" link is invalid or too old; sign in and use "Log out of all devices" in settings instead. */
  | 'SIGN_OUT_LINK_EXPIRED'
  /** The SMS provider didn't accept the code message; try again later. */
  | 'SMS_NOT_SENT'
  /** The task already has a booking in progress; no other offer can be accepted. */
  | 'TASK_ALREADY_BOOKED'
  /** An offer on the task was accepted, so only its photos and, while the booking is active, its access details can change. A new date goes through a reschedule with the helper. */
  | 'TASK_BOOKED'
  /** The task can't be changed this way: a draft is saved with saveTaskDraft and published once, and a closed task can't be changed. */
  | 'TASK_NOT_EDITABLE'
  /** No such task, or not one the caller may see or change. */
  | 'TASK_NOT_FOUND'
  /** The task no longer takes offers: it is closed, booked, or its date has passed. */
  | 'TASK_NOT_OPEN_FOR_OFFERS'
  /** The task lies outside the service areas on your helper profile; add its area with updateHelperProfile to offer on it. */
  | 'TASK_OUTSIDE_HELPER_AREAS'
  /** The account details or acceptCurrentTerms didn't accept the current terms and conditions: the version is missing or isn't `currentLegalDocument(kind: TERMS)`'s version (they may have just changed). Fetch the current version, show it, and ask again. */
  | 'TERMS_NOT_ACCEPTED'
  /** The terms changed and the user hasn't accepted the version in force (`viewer.accountState` is TERMS_UPDATE_REQUIRED). Until they do they can't post, offer or book, but can view history, finish open bookings, export data and delete the account. */
  | 'TERMS_UPDATE_REQUIRED'
  /** Too many uploads not used yet (started, being processed, or ready and not attached to anything); use them or wait for them to expire. */
  | 'TOO_MANY_PENDING_UPLOADS'
  /** The operation needs a signed-in user and none was authenticated. */
  | 'UNAUTHENTICATED'
  /** The person didn't confirm they are 18 or older. */
  | 'UNDERAGE'
  /** The file was replaced after completeUpload; start a new upload. */
  | 'UPLOAD_CHANGED'
  /** The file isn't a readable image of the type it was uploaded as. */
  | 'UPLOAD_INVALID_IMAGE'
  /** No such upload of the signed-in user, or it can't be used here (not ready, another purpose, or already attached). */
  | 'UPLOAD_NOT_FOUND'
  /** The file hasn't arrived in storage; PUT it to the upload URL first. */
  | 'UPLOAD_NOT_RECEIVED'
  /** The photo is larger than the upload limit, in bytes or in pixels. */
  | 'UPLOAD_TOO_LARGE'
  /** Photos must be JPEG, PNG or WebP. */
  | 'UPLOAD_TYPE_NOT_ALLOWED'
  /** Joining the waitlist needs consent to the one launch email. */
  | 'WAITLIST_CONSENT_REQUIRED'
  /** There is no withdrawal right to use on this booking: the helper is a private individual, or the 14-day withdrawal period is over. Cancel instead. */
  | 'WITHDRAWAL_NOT_AVAILABLE'
  /** The booking's start time has passed, so the poster can't cancel it themselves; open a dispute, or use the withdrawal button while it is offered. */
  | 'WORK_STARTED';

export type HelperAddressInput = {
  city: string;
  /** ISO 3166-1 alpha-2; must be HR, else HELPER_ADDRESS_NOT_IN_CROATIA. */
  country: string;
  postalCode: string;
  street: string;
};

/** Where the obrt or company is registered; never the home address. */
export type HelperBusinessAddressInput = {
  city: string;
  /** ISO 3166-1 alpha-2, an EU member state. */
  country: string;
  postalCode: string;
  street: string;
};

export type HelperBusinessInput = {
  /** The trader issues a fiscalized invoice for each task. */
  issuesFiscalizedInvoices?: boolean;
  kind: HelperBusinessKind;
  name: string;
  /** The company's OIB, required for COMPANY. An obrt's OIB is its owner's own: leave it out for OBRT (or give the same OIB). */
  oib?: string | null | undefined;
};

export type HelperBusinessKind =
  | 'COMPANY'
  | 'OBRT';

/** Why the helper cancels. The no-fault reasons have their own flow. */
export type HelperCancelReason =
  | 'CANT_COME'
  | 'DOUBLE_BOOKED'
  | 'ILL'
  | 'OTHER';

/** Something a helper still has to provide before sending offers. */
export type HelperRequirement =
  | 'ADDRESS'
  | 'BIRTH_DATE'
  | 'BUSINESS_ADDRESS'
  | 'BUSINESS_DETAILS'
  | 'BUSINESS_VERIFICATION'
  | 'CATEGORIES'
  | 'IBAN'
  | 'LEGAL_NAME'
  | 'OIB'
  | 'PAYOUT_ACCOUNT'
  | 'PHONE_VERIFIED'
  | 'RESIDENCE_COUNTRY'
  | 'SERVICE_AREAS'
  | 'STATUS';

/** The status a helper declares. */
export type HelperStatus =
  /** A registered business, obrt or company: shown as a trader. */
  | 'BUSINESS'
  | 'PENSIONER'
  | 'PRIVATE_INDIVIDUAL'
  /** Helps as a private individual; student-service contracts aren't offered. */
  | 'STUDENT';

export type JoinWaitlistInput = {
  category: TaskCategory;
  /** The city the person wanted help in, as typed. */
  city: string;
  /** The person ticked the consent to one email when TaskBeavo launches in this city, and nothing else. Must be true. */
  consentLaunchEmail: boolean;
  /** ISO 3166-1 alpha-2 country of the city. */
  countryCode: string;
  email: string;
  /** The language the consent was shown in; the launch email uses it. */
  locale: Locale;
};

/** A kind of legal document. */
export type LegalDocumentKind =
  | 'CANCELLATION'
  | 'COOKIES'
  | 'HELPER_TERMS'
  | 'IMPRINT'
  | 'PRIVACY'
  | 'TERMS';

/** A language TaskBeavo is available in. */
export type Locale =
  | 'DE'
  | 'EN'
  | 'FR'
  | 'HR';

/** Support's decision on a no-fault request. */
export type NoFaultDecision =
  /** The ordinary policy applies to whoever asked, as of when they asked. */
  | 'REJECTED'
  /** Nobody's fault: full refund. */
  | 'UPHELD';

/** What the other side sees of a no-fault reason: hospitalisation, bereavement and emergency all show as PERSONAL_EMERGENCY (GDPR Art. 9). */
export type NoFaultLabel =
  | 'HELPER_LATE'
  | 'MUTUAL_AGREEMENT'
  | 'PERSONAL_EMERGENCY'
  | 'WEATHER';

/** A reason that makes a cancellation nobody's fault: a full refund once the other side agrees, or support upholds it. */
export type NoFaultReason =
  | 'BEREAVEMENT'
  | 'EMERGENCY'
  | 'HELPER_LATE'
  | 'HOSPITALISATION'
  | 'MUTUAL_AGREEMENT'
  | 'WEATHER';

/** How the other side answered a no-fault request. */
export type NoFaultResponse =
  | 'AGREED'
  | 'DISAGREED'
  /** No answer within 48 hours: the poster's request stands; the helper's goes to support. */
  | 'NO_REPLY';

export type OfferStatus =
  /** The poster accepted it; it is being booked. */
  | 'ACCEPTED'
  /** The poster accepted another offer. It reopens if that checkout fails. */
  | 'DECLINED'
  /** Past its expiry; the helper may renew it. */
  | 'EXPIRED'
  /** The poster changed the task's date, address or scope; the helper confirms or changes the offer with updateOffer. */
  | 'NEEDS_UPDATE'
  | 'SENT'
  | 'WITHDRAWN';

export type OfferWithdrawnReason =
  /** The task's poster books for a business, so the task takes offers from registered helpers only. It says nothing about the helper. */
  | 'BUSINESS_POSTER_REGISTERED_ONLY';

/** A card attempt during checkout, as Stripe's webhook reported it. */
export type PaymentAttemptKind =
  /** The bank asked the cardholder to confirm, in 3D Secure or a banking app. */
  | 'AUTHENTICATION_STARTED'
  /** The card was declined or 3D Secure failed; try again or another card. */
  | 'DECLINED';

/** Why Stripe rejected a payout account, as far as the helper is told. */
export type PayoutAccountRejection =
  | 'INCOMPLETE_VERIFICATION'
  | 'OTHER'
  | 'TERMS_OF_SERVICE';

/** Where the helper's Stripe payout account stands. */
export type PayoutAccountStatus =
  /** Can receive payments. */
  | 'ACTIVE'
  /** Stripe onboarding isn't finished: continue with startPayoutOnboarding. */
  | 'INCOMPLETE'
  /** Stripe asks for more information; offers are paused until it is given (startPayoutOnboarding). */
  | 'NEEDS_INFO'
  /** Stripe rejected the account; support explains why and how to appeal. */
  | 'REJECTED'
  /** Stripe paused the account (for example under review); support helps. */
  | 'RESTRICTED'
  /** Everything was given and Stripe is checking it. */
  | 'VERIFYING';

export type PosterBusinessInput = {
  kind: PosterBusinessKind;
  /** The obrt's or company's name, up to 200 characters. */
  name: string;
  /** The company's OIB, or for an obrt its owner's own OIB; 11 digits. */
  oib: string;
};

/** The kind of registered business a poster books for. */
export type PosterBusinessKind =
  | 'COMPANY'
  | 'OBRT';

/** Why the poster cancels. The no-fault reasons have their own flow. */
export type PosterCancelReason =
  | 'DIFFERENT_DATE'
  | 'HELPER_ASKED'
  | 'NO_LONGER_NEEDED'
  | 'OTHER';

export type ProviderSignInInput = {
  /** Apple only: the given name Apple handed the app on the first sign-in. */
  firstName?: string;
  /** The ID token Google or Apple returned. */
  idToken: string;
  /** Apple only: the family name Apple handed the app on the first sign-in. */
  lastName?: string;
  /** The nonce from requestSignInNonce, unhashed. */
  nonce: string;
  provider: SignInProvider;
};

export type SendOfferInput = {
  /** Optional, up to 1000 characters. */
  message?: string;
  /** Euro cents; at least 1000. */
  priceCents: number;
  taskId: string | number;
};

/** Where a service fee price list stands today. */
export type ServiceFeeScheduleStatus =
  | 'CURRENT'
  | 'EARLIER'
  | 'UPCOMING';

/** Whether the service fee includes VAT. UNDECIDED until the accountant picks INCLUDED (variant A) or NOT_CHARGED (variant B); show neither while UNDECIDED. */
export type ServiceFeeVat =
  | 'INCLUDED'
  | 'NOT_CHARGED'
  | 'UNDECIDED';

/** Where a session signed in. */
export type SessionPlatform =
  | 'ANDROID'
  | 'IOS'
  | 'WEB';

/** A sign-in provider. */
export type SignInProvider =
  | 'APPLE'
  | 'GOOGLE';

/** What kind of help a task asks for. */
export type TaskCategory =
  | 'CHECK_IN'
  | 'CLEANING'
  | 'ERRANDS'
  | 'GARDEN'
  | 'REPAIRS';

/** Why a task waits for review. */
export type TaskHoldReason =
  /** The text may contain contact details. */
  | 'CONTACT_DETAILS'
  /** The text reads like a ride, medical care or personal care. */
  | 'EXCLUDED_CATEGORY';

/** Every field of a task. Omitted fields stay as they are on edits. */
export type TaskInput = {
  accessDetails?: string | null | undefined;
  budgetCents?: number | null | undefined;
  /** One of your on-site contacts; "" removes it. */
  careContactId?: string | number | null | undefined;
  /** TaskCategory lists only categories TaskBeavo accepts, so rides, medical and personal care fail schema validation. */
  category?: TaskCategory | null | undefined;
  description?: string | null | undefined;
  flexibleDate?: boolean | null | undefined;
  location?: TaskLocationInput | null | undefined;
  /** Your READY task-photo uploads, in order; replaces the task's photos. */
  photoIds?: Array<string | number> | null | undefined;
  title?: string | null | undefined;
  windowEnd?: unknown;
  windowStart?: unknown;
};

export type TaskLocationInput = {
  /** The exact address; shown to the poster only. */
  address: string;
  lat: number;
  lng: number;
};

export type TaskStatus =
  | 'CLOSED'
  | 'DRAFT'
  | 'OPEN'
  /** Published but held until staff check it; see `holdReasons`. */
  | 'PENDING_REVIEW';

/** Something the poster should know; not an error. */
export type TaskWarning =
  /** You already have an open task at this address on this day. */
  | 'DUPLICATE_TASK';

export type UpdateCareContactInput = {
  area?: string | null | undefined;
  language?: Locale | null | undefined;
  name?: string | null | undefined;
  noSmartphone?: boolean | null | undefined;
  phone?: string | null | undefined;
};

/** Fields to set; omitted fields stay as they are. */
export type UpdateHelperProfileInput = {
  address?: HelperAddressInput | null | undefined;
  birthDate?: unknown;
  /** Only with the BUSINESS status. */
  business?: HelperBusinessInput | null | undefined;
  /** The registered business address, only with the BUSINESS status. The poster of a task sees it on the helper's offer, at checkout and in the contract confirmation; the public profile shows only the town. */
  businessAddress?: HelperBusinessAddressInput | null | undefined;
  /** Replaces the categories. */
  categories?: Array<TaskCategory> | null | undefined;
  /** An EU account; spaces are ignored. */
  iban?: string | null | undefined;
  legalFirstName?: string | null | undefined;
  legalLastName?: string | null | undefined;
  oib?: string | null | undefined;
  residenceCountry?: string | null | undefined;
  /** Replaces the service areas; IDs from serviceAreas. */
  serviceAreaIds?: Array<string | number> | null | undefined;
  /** Changing away from BUSINESS removes the business details. */
  status?: HelperStatus | null | undefined;
  /** Empty string ("") removes it. */
  vatId?: string | null | undefined;
};

/** Fields to change; omit all of them to confirm the offer as it is. */
export type UpdateOfferInput = {
  message?: string | null | undefined;
  priceCents?: number | null | undefined;
};

/** What a photo is for. Decides who may see it and what is kept. */
export type UploadPurpose =
  /** Proof for a booking. Private; its capture time and position are kept server-side and viewers see a copy without metadata. */
  | 'EVIDENCE_PHOTO'
  /** Shown to other users; stored without any metadata (no GPS). */
  | 'TASK_PHOTO';

/** Where an upload is in its life. */
export type UploadStatus =
  /** Waiting for the PUT and completeUpload. */
  | 'PENDING'
  /** Received; being checked and cleaned. */
  | 'PROCESSING'
  /** Ready to use; `url` is set for the owner. */
  | 'READY'
  /** Not a valid image; see `rejectionCode`. */
  | 'REJECTED';

